// Evidence-backed request-path tests for the Payments leaf (Phase 3.1).
//
// Generated by scripts/research/gen-31-tests.py from the rows in api.md, which in turn come from
// docs/research/apk-endpoints.md. Each test calls the method and inspects the URL that actually
// reaches `fetch`, so a rename or a route regression fails here rather than in production.

import BandlabSDK from 'bandlab-sdk';

function makeClient(): BandlabSDK {
  return new BandlabSDK({ bearerToken: 'My Bearer Token', baseURL: 'http://127.0.0.1:4010' });
}

/** Run `fn`, capture the URL of the first request, and answer it with a stub response. */
async function captureURL(fn: (c: BandlabSDK) => Promise<unknown>): Promise<string> {
  const calls: string[] = [];
  const realFetch = globalThis.fetch;
  globalThis.fetch = (async (input: any) => {
    calls.push(typeof input === 'string' ? input : input?.url ?? String(input));
    return new Response('{}', { status: 200, headers: { 'content-type': 'application/json' } });
  }) as typeof fetch;
  try {
    await fn(makeClient()).catch(() => undefined);
  } finally {
    globalThis.fetch = realFetch;
  }
  if (!calls.length) throw new Error('no request was issued');
  return calls[0]!;
}

describe('Payments paths match the APK evidence', () => {
  test('POST /checkout/products/beats/payment-providers/google-play-store/payment-intents hits /checkout/products/beats/payment-providers/google-play-store/payment-intents', async () => {
    const url = await captureURL((c) => c.payments.createBeatPaymentIntent({}));
    expect(url).toContain('/checkout/products/beats/payment-providers/google-play-store/payment-intents');
  });

  test('POST /checkout/products/boost-profile/payment-providers/google-play-store/payment-intents hits /checkout/products/boost-profile/payment-providers/google-play-store/payment-intents', async () => {
    const url = await captureURL((c) => c.payments.createBoostProfilePaymentIntent({}));
    expect(url).toContain(
      '/checkout/products/boost-profile/payment-providers/google-play-store/payment-intents',
    );
  });

  test('POST /checkout/products/boost/payment-providers/google-play-store/payment-intents hits /checkout/products/boost/payment-providers/google-play-store/payment-intents', async () => {
    const url = await captureURL((c) => c.payments.createBoostPaymentIntent({}));
    expect(url).toContain('/checkout/products/boost/payment-providers/google-play-store/payment-intents');
  });

  test('POST /checkout/products/membership/payment-providers/google-play-store/payment-intents hits /checkout/products/membership/payment-providers/google-play-store/payment-intents', async () => {
    const url = await captureURL((c) => c.payments.createMembershipPaymentIntent({}));
    expect(url).toContain(
      '/checkout/products/membership/payment-providers/google-play-store/payment-intents',
    );
  });

  test('POST /checkout/products/membership/payment-providers/google-play-store/payment-intents/{paymentIntentID}/payment-confirmations hits /checkout/products/membership/payment-providers/google-play-store/payment-intents/{paymentIntentID}/payment-confirmations', async () => {
    const url = await captureURL((c) =>
      c.payments.confirmMembershipPayment('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e', {}),
    );
    expect(url).toContain(
      '/checkout/products/membership/payment-providers/google-play-store/payment-intents/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/payment-confirmations',
    );
  });

  test('POST /checkout/products/{product}/payment-providers/google-play-store/payment-intents/{paymentIntentID}/payment-confirmations hits /checkout/products/{product}/payment-providers/google-play-store/payment-intents/{paymentIntentID}/payment-confirmations', async () => {
    const url = await captureURL((c) =>
      c.payments.confirmPayment('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e', {
        product: '182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e',
      }),
    );
    expect(url).toContain(
      '/checkout/products/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/payment-providers/google-play-store/payment-intents/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/payment-confirmations',
    );
  });
});
